54	func loadBenchSet(path string) (*benchSet, error) {
55		raw, err := os.ReadFile(path) // #nosec G304 -- operator-supplied bench-set path
56		if err != nil {
57			return nil, fmt.Errorf("read bench-set %s: %w", path, err)
58		}
59		var r rawBenchSet
60		dec := yaml.NewDecoder(strings.NewReader(string(raw)))
61		dec.KnownFields(true)
62		if err := dec.Decode(&r); err != nil {
63			return nil, fmt.Errorf("parse bench-set %s: %w", path, err)
64		}
65		bs := &benchSet{
66			ID:          r.ID,
67			Framework:   r.Framework,
68			Dataset:     r.Dataset,
69			DefaultReps: r.DefaultReps,
70			Description: strings.TrimSpace(r.Description),
71		}
72		switch r.Tasks.Kind {
73		case yaml.ScalarNode:
74			if strings.TrimSpace(r.Tasks.Value) != "all" {
75				return nil, fmt.Errorf("bench-set %s: tasks scalar must be \"all\", got %q", path, r.Tasks.Value)
76			}
77			bs.AllTasks = true
78		case yaml.SequenceNode:
79			for _, child := range r.Tasks.Content {
80				if child.Kind != yaml.ScalarNode {
81					return nil, fmt.Errorf("bench-set %s: tasks entries must be scalars", path)
82				}
83				v := strings.TrimSpace(child.Value)
84				if v == "" {
85					continue
86				}
87				bs.Tasks = append(bs.Tasks, v)
88			}
89		case 0:
90			return nil, fmt.Errorf("bench-set %s: tasks field is required", path)
91		default:
92			return nil, fmt.Errorf("bench-set %s: unsupported tasks node kind %v", path, r.Tasks.Kind)
93		}
94		if err := bs.validate(); err != nil {
95			return nil, fmt.Errorf("validate bench-set %s: %w", path, err)
96		}
97		return bs, nil
98	}
