86					if shouldUpdateGolden() {
87						if err := os.WriteFile(fixturePath, got, 0o644); err != nil {
88							t.Fatalf("rewrite fixture: %v", err)
89						}
90						t.Logf("updated %s", fixturePath)
91						return
92					}
93					t.Fatalf("plan output drift; rerun with -update or compare with:\n  diff %s <(go run ./cmd/bench plan --profile %s --bench-set %s --json --profiles-dir %s --bench-sets-dir %s --concurrency-groups %s)",
94						fixturePath, c.profileList, c.benchSetID, profilesDir, benchSetsDir, concurrencyPath)
95				}
96	
97				// Sanity: cell count = profiles × tasks × default_reps.
98				expected := len(profiles) * len(bs.Tasks) * bs.DefaultReps
99				if len(plan.Cells) != expected {
100					t.Fatalf("cells: got %d, want %d", len(plan.Cells), expected)
101				}
102			})
103		}
104	}
